using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.SceneManagement;

// Generated by Claude Opus 5.5
// Shows a placeholder win or lose menu when the game ends.
public class MenuManager : MonoBehaviour
{
    [SerializeField]
    private GameManager game;

    [SerializeField]
    private GameObject winMenu;

    [SerializeField]
    private GameObject loseMenu;

    // Generated by Claude Opus 5.5
    void Awake()
    {
        this.winMenu.SetActive(false);
        this.loseMenu.SetActive(false);
        this.game.GameEnded += this.Show;
    }

    // Generated by Claude Opus 5.5
    // Press R after the game ends to restart from the beginning.
    void Update()
    {
        Keyboard keyboard = Keyboard.current;
        if (!this.game.GameStarted && keyboard != null && keyboard.rKey.wasPressedThisFrame)
        {
            SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);
        }
    }

    // Generated by Claude Opus 5.5
    private void Show(bool win)
    {
        this.winMenu.SetActive(win);
        this.loseMenu.SetActive(!win);
    }
}
